import { defineConfig, devices } from '@playwright/test';
import { fileURLToPath } from 'node:url';

const dir = (p: string) => fileURLToPath(new URL(p, import.meta.url));

/** The fake camera clip, generated by globalSetup before any test runs. */
export const FAKE_VIDEO = dir('./tests/fixtures/moving-marker.y4m');

export default defineConfig({
  testDir: './tests/e2e',
  globalSetup: dir('./tests/e2e/globalSetup.ts'),
  // Detection plus an 11 MB WASM load is not a fast test.
  timeout: 120_000,
  expect: { timeout: 30_000 },
  fullyParallel: false,
  workers: 1,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? [['github'], ['list']] : [['list']],

  use: {
    baseURL: 'http://localhost:4173',
    trace: 'retain-on-failure',
    video: 'off',
  },

  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        permissions: ['camera'],
        launchOptions: {
          args: [
            // Grant the camera prompt automatically, and serve a known clip
            // instead of real hardware, so the test is deterministic and runs
            // on a headless CI box with no webcam.
            '--use-fake-ui-for-media-stream',
            '--use-fake-device-for-media-stream',
            `--use-file-for-fake-video-capture=${FAKE_VIDEO}`,
            // Headless Chromium falls back to SwiftShader for WebGL; without
            // this, some CI images refuse to create a GL context at all.
            '--enable-unsafe-swiftshader',
          ],
        },
      },
    },
  ],

  // Tests run against the production build, so the service worker and the
  // real chunking are exercised rather than the dev server's.
  webServer: {
    command: 'npm run build && npx vite preview --port 4173 --strictPort',
    url: 'http://localhost:4173/index.html',
    reuseExistingServer: !process.env.CI,
    timeout: 300_000,
    stdout: 'pipe',
    stderr: 'pipe',
  },
});
